import 'package:flutter/material.dart';
import 'track_item.dart';

/// Vector art style for autogenerated YouTube Music-style procedural covers
enum ForYouArtStyle {
  geometricPulse,
  sonicWave,
  radialDisc,
  orbitBloom,
  starburst;

  String get label {
    switch (this) {
      case ForYouArtStyle.geometricPulse:
        return 'Geometric Pulse';
      case ForYouArtStyle.sonicWave:
        return 'Sonic Wave';
      case ForYouArtStyle.radialDisc:
        return 'Radial Vinyl';
      case ForYouArtStyle.orbitBloom:
        return 'Orbit Bloom';
      case ForYouArtStyle.starburst:
        return 'Starburst';
    }
  }
}

/// Autogenerated algorithmic mix model for the "For You" page
class ForYouMix {
  final String id;
  final String title;
  final String subtitle;
  final String vibeCategory;
  final List<TrackItem> tracks;
  final Color primaryColor;
  final Color secondaryColor;
  final ForYouArtStyle artStyle;
  final String badge;

  const ForYouMix({
    required this.id,
    required this.title,
    required this.subtitle,
    required this.vibeCategory,
    required this.tracks,
    required this.primaryColor,
    required this.secondaryColor,
    required this.artStyle,
    required this.badge,
  });
}
